//! Generates the Rust side of include/apus/abi.h and checks that the committed files are up to date:
//! `src/bindings.rs` (bindgen), `src/symbols.rs` (the runtime symbols the self-check resolves), `src/optional.rs` and
//! `src/bindings_macos15.rs` (macOS 15 declarations). `APUS_BLESS=1` rewrites them. When the committed files were
//! generated by another libclang, the comparison is skipped: another Xcode can change bindgen's output by itself.
#[path = "support/ast.rs"]
mod ast;

use ast::{Decl, Kind};
use std::fmt::Write;
use std::path::Path;

const BINDGEN: &str = "0.73.2";

/// FNV-1a of the header text: which abi.h a generated file came from, whatever clang generated it.
fn header_hash() -> String {
    let text = std::fs::read(ast::header()).unwrap();
    let hash = text.iter().fold(0xcbf29ce484222325u64, |h, b| (h ^ *b as u64).wrapping_mul(0x100000001b3));
    format!("{hash:016x}")
}

fn header_lines(clang: &str, hash: &str) -> String {
    format!(
        "// @generated by sys/tests/fresh.rs from include/apus/abi.h with bindgen {BINDGEN}; do not edit.\n// clang: {clang}\n// abi.h: {hash}\n"
    )
}

/// A generated file without its `// clang:` line, which only records who generated it.
fn without_clang_line(text: &str) -> String {
    text.lines().filter(|l| !l.starts_with("// clang: ")).collect::<Vec<_>>().join("\n")
}

fn bindings(decls: &[Decl]) -> String {
    // macOS 15 declarations stay out of the always-linked bindings: optional.rs and bindings_macos15.rs carry them.
    let optional = decls.iter().filter(|d| d.available.is_some()).fold(String::new(), |all, d| {
        if all.is_empty() { format!("^{}$", d.name) } else { format!("{all}|^{}$", d.name) }
    });
    let builder = if optional.is_empty() { bindgen::Builder::default() } else { bindgen::Builder::default().blocklist_function(optional) };
    builder
        .header(ast::header().to_str().unwrap())
        .clang_args(["-xc", "-DAPUS_BINDGEN", &format!("-I{}", ast::include_dir().display())])
        .allowlist_file(".*/include/apus/.*")
        .layout_tests(true)
        .generate()
        .expect("bindgen failed on include/apus/abi.h")
        .to_string()
}

/// Our own C functions (funclets and thunks) are not runtime symbols.
fn is_runtime(decl: &Decl) -> bool {
    decl.kind != Kind::FunctionType && !decl.marker.is_empty() && !decl.name.starts_with("rs_") && !decl.name.starts_with("apus_")
}

fn symbols(decls: &[Decl]) -> String {
    let mut out = String::from("/// Every runtime symbol the header declares (funclets included); the self-check resolves each one.\npub const REQUIRED_SYMBOLS: &[&str] = &[\n");
    for d in decls.iter().filter(|d| is_runtime(d) && d.available.is_none()) {
        writeln!(out, "    {:?},", d.link_name).unwrap();
    }
    out.push_str("];\n\n/// Runtime symbols of newer OS releases: (symbol, (major, minor) of the macOS that introduced it).\npub const OPTIONAL_SYMBOLS: &[(&str, (u32, u32))] = &[\n");
    for d in decls.iter().filter(|d| is_runtime(d)) {
        if let Some(version) = &d.available {
            let (major, minor) = version.split_once('.').unwrap_or((version, "0"));
            writeln!(out, "    ({:?}, ({major}, {minor})),", d.link_name).unwrap();
        }
    }
    out.push_str("];\n");
    out
}

/// The Rust spelling of a C type the header uses in an optional declaration.
fn rust_type(c: &str) -> String {
    match c {
        "void" => "()".into(),
        "void *" => "*mut c_void".into(),
        "const void *" => "*const c_void".into(),
        "size_t" => "usize".into(),
        "intptr_t" => "isize".into(),
        "uint8_t" => "u8".into(),
        "uint32_t" => "u32".into(),
        "uint64_t" => "u64".into(),
        "bool" => "bool".into(),
        name if name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_') => name.into(),
        other => panic!("fresh.rs: add a Rust spelling for the C type `{other}`"),
    }
}

/// The tag apus-sys's version gives the boundary namespace: `<version with . as _>_<FNV-1a, low 32 bits, hex>`.
fn expected_tag() -> String {
    let version = env!("CARGO_PKG_VERSION");
    let hash = version.bytes().fold(0xcbf29ce484222325u64, |h, b| (h ^ b as u64).wrapping_mul(0x100000001b3));
    format!("{}_{:08x}", version.replace('.', "_"), hash & 0xffff_ffff)
}

fn header_tag() -> String {
    let text = std::fs::read_to_string(ast::header()).unwrap();
    let line = text.lines().find(|l| l.starts_with("#define APUS_TAG ")).expect("abi.h defines APUS_TAG");
    line.trim_start_matches("#define APUS_TAG ").trim().trim_matches('"').to_string()
}

/// The link-name prefix, and the link name of every boundary function Rust implements (declared without a marker).
fn boundary(decls: &[Decl]) -> String {
    let prefix = format!("apus_{}_", header_tag());
    let mut out = format!("/// The link-name prefix of the C<->Rust boundary symbols apus defines.\npub const BOUNDARY_PREFIX: &str = {prefix:?};\n\n");
    out.push_str("/// The link name of a boundary function Rust implements, for `#[export_name = …]`.\n#[macro_export]\nmacro_rules! boundary_name {\n");
    for d in decls.iter().filter(|d| d.kind == Kind::Function && d.marker.is_empty() && d.link_name.starts_with(&prefix)) {
        writeln!(out, "    ({}) => {{ {:?} }};", d.name, d.link_name).unwrap();
    }
    out.push_str("}\n");
    out
}

fn optional_decls(decls: &[Decl]) -> Vec<&Decl> {
    let found: Vec<&Decl> = decls.iter().filter(|d| d.available.is_some()).collect();
    for d in &found {
        assert!(d.kind == Kind::Function && (d.marker == "direct" || d.marker == "c"), "{}: only APUS_DIRECT/APUS_C functions can be optional yet", d.name);
    }
    found
}

fn signature(d: &Decl) -> (String, String) {
    let params = d.params.iter().enumerate().map(|(i, t)| format!("a{i}: {}", rust_type(t))).collect::<Vec<_>>().join(", ");
    let ret = if d.ret == "void" { String::new() } else { format!(" -> {}", rust_type(&d.ret)) };
    (params, ret)
}

fn optional(decls: &[Decl]) -> String {
    let mut out = String::from("#[allow(unused_imports)]\nuse std::ffi::c_void;\n");
    let found = optional_decls(decls);
    if !found.is_empty() {
        out.push_str("#[cfg(not(feature = \"macos15\"))]\nextern \"C\" {\n    fn dlsym(handle: *mut c_void, symbol: *const std::ffi::c_char) -> *mut c_void;\n}\n#[cfg(not(feature = \"macos15\"))]\nconst RTLD_DEFAULT: *mut c_void = -2isize as *mut c_void;\n");
    }
    for d in found {
        let (_, ret) = signature(d);
        let types = d.params.iter().map(|t| rust_type(t)).collect::<Vec<_>>().join(", ");
        let pointer = format!("unsafe extern \"C\" fn({types}){ret}");
        let version = d.available.as_deref().unwrap();
        write!(
            out,
            r#"
/// `{name}` (macOS {version}+): `None` on an older OS. With the `macos15` feature it is linked and always present.
pub fn {name}() -> Option<{pointer}> {{
    #[cfg(feature = "macos15")]
    {{
        Some(super::{name})
    }}
    #[cfg(not(feature = "macos15"))]
    {{
        static ADDRESS: std::sync::OnceLock<usize> = std::sync::OnceLock::new();
        let address = *ADDRESS.get_or_init(|| unsafe {{ dlsym(RTLD_DEFAULT, c"{link}".as_ptr()) }} as usize);
        (address != 0).then(|| unsafe {{ std::mem::transmute::<usize, {pointer}>(address) }})
    }}
}}
"#,
            name = d.name,
            link = d.link_name,
        )
        .unwrap();
    }
    out
}

fn bindings_macos15(decls: &[Decl]) -> String {
    let found = optional_decls(decls);
    if found.is_empty() {
        return String::new();
    }
    let mut out = String::from("extern \"C\" {\n");
    for d in found {
        let (params, ret) = signature(d);
        if d.link_name != d.name {
            writeln!(out, "    #[link_name = {:?}]", d.link_name).unwrap();
        }
        writeln!(out, "    pub fn {}({params}){ret};", d.name).unwrap();
    }
    out.push_str("}\n");
    out
}

fn main() {
    let clang = bindgen::clang_version().full;
    let decls = ast::declarations(&[]);
    let hash = header_hash();
    let top = header_lines(&clang, &hash);
    let files = [
        ("bindings.rs", format!("{top}{}", bindings(&decls))),
        ("symbols.rs", format!("{top}{}", symbols(&decls))),
        ("optional.rs", format!("{top}{}", optional(&decls))),
        ("bindings_macos15.rs", format!("{top}{}", bindings_macos15(&decls))),
        ("boundary.rs", format!("{top}{}", boundary(&decls))),
    ];
    assert_eq!(header_tag(), expected_tag(), "APUS_TAG in include/apus/abi.h must follow apus-sys's version");
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("src");
    if std::env::var_os("APUS_BLESS").is_some() {
        for (name, contents) in &files {
            std::fs::write(dir.join(name), contents).unwrap();
        }
        return println!("fresh ... blessed");
    }
    // Files built from the AST by this test do not depend on bindgen's output format: always compared. bindings.rs
    // is compared only when generated by this libclang; with another, it must still come from this abi.h.
    let mut stale = Vec::new();
    let mut skipped = None;
    for (name, contents) in &files {
        let committed = std::fs::read_to_string(dir.join(name)).unwrap_or_default();
        let committed_clang = committed.lines().nth(1).and_then(|l| l.strip_prefix("// clang: ")).unwrap_or("");
        let committed_hash = committed.lines().nth(2).and_then(|l| l.strip_prefix("// abi.h: ")).unwrap_or("");
        let fresh = if *name == "bindings.rs" && !committed.is_empty() && committed_clang != clang {
            skipped = Some(committed_clang.to_string());
            committed_hash == hash
        } else {
            without_clang_line(&committed) == without_clang_line(contents)
        };
        if !fresh {
            stale.push(format!("{name} is stale (include/apus/abi.h changed); run APUS_BLESS=1 cargo test -p apus-sys --test fresh"));
        }
    }
    if let (Some(other), true) = (&skipped, stale.is_empty()) {
        return println!("fresh ... ok (bindings.rs compared by header hash only: generated with {other}, this is {clang})");
    }
    if stale.is_empty() {
        println!("fresh ... ok");
    } else {
        eprintln!("{}", stale.join("\n"));
        std::process::exit(1);
    }
}
